function brl(v){return Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})} function num(j){return String(j||'').split('@')[0].replace(/\D/g,'')} function jid(n){return String(n).replace(/\D/g,'')+'@s.whatsapp.net'}
function keyBuffer(){const file=path.join(DATA_DIR,'config.key');if(!fs.existsSync(file))fs.writeFileSync(file,crypto.randomBytes(32),{mode:0o600});return fs.readFileSync(file)}
function seal(value){const iv=crypto.randomBytes(12),cipher=crypto.createCipheriv('aes-256-gcm',keyBuffer(),iv),body=Buffer.concat([cipher.update(String(value),'utf8'),cipher.final()]),tag=cipher.getAuthTag();return Buffer.concat([iv,tag,body]).toString('base64')}
function open(value){try{const b=Buffer.from(value,'base64'),iv=b.subarray(0,12),tag=b.subarray(12,28),body=b.subarray(28),dec=crypto.createDecipheriv('aes-256-gcm',keyBuffer(),iv);dec.setAuthTag(tag);return Buffer.concat([dec.update(body),dec.final()]).toString('utf8')}catch{return ''}}
function passwordHash(password,salt){return crypto.scryptSync(password,salt,64).toString('hex')}
async function loadSettings(){const rows=await all('SELECT chave,valor FROM configuracoes');settings=Object.fromEntries(rows.map(x=>[x.chave,open(x.valor)]));return settings}
async function saveSetting(key,value){await run('INSERT OR REPLACE INTO configuracoes(chave,valor) VALUES(?,?)',[key,seal(value)]);settings[key]=String(value)}
function isoBahia(date=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:TZ,year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}
function addDays(date,days){const d=new Date(date+'T12:00:00-03:00');d.setDate(d.getDate()+days);return isoBahia(d)}
function dateFromParts(year,month,day){return `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`}
function nthWeekday(year,month,weekday,n){const d=new Date(Date.UTC(year,month-1,1,12));const delta=(weekday-d.getUTCDay()+7)%7;d.setUTCDate(1+delta+(n-1)*7);return isoBahia(d)}
function easterDate(year){const a=year%19,b=Math.floor(year/100),c=year%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),month=Math.floor((h+l-7*m+114)/31),day=((h+l-7*m+114)%31)+1;return dateFromParts(year,month,day)}
function campaignDates(year){const easter=easterDate(year);return {ano_novo:dateFromParts(year,1,1),carnaval:addDays(easter,-47),pascoa:easter,dia_maes:nthWeekday(year,5,0,2),dia_namorados:dateFromParts(year,6,12),sao_joao:dateFromParts(year,6,24),ferias:dateFromParts(year,7,1),dia_pais:nthWeekday(year,8,0,2),primavera:dateFromParts(year,9,22),dia_criancas:dateFromParts(year,10,12),black_friday:addDays(nthWeekday(year,11,4,4),1),natal:dateFromParts(year,12,25),reveillon:dateFromParts(year,12,31)}}
