 await run(`CREATE TABLE IF NOT EXISTS campanhas(id TEXT PRIMARY KEY, nome TEXT NOT NULL, ativo INTEGER DEFAULT 1, antecedencia INTEGER DEFAULT 7, texto TEXT NOT NULL, imagem TEXT, updated_at TEXT DEFAULT CURRENT_TIMESTAMP)`);
 await run(`CREATE TABLE IF NOT EXISTS envios_automaticos(chave TEXT PRIMARY KEY, enviado_em TEXT DEFAULT CURRENT_TIMESTAMP)`);
