 for(const c of CAMPAIGNS){await run(`INSERT OR IGNORE INTO campanhas(id,nome,ativo,antecedencia,texto,imagem) VALUES(?,?,1,?,?,?)`,[c.id,c.nome,c.dias,c.texto,`${c.id}.jpg`]);await run('UPDATE campanhas SET imagem=? WHERE id=? AND (imagem IS NULL OR imagem="")',[`${c.id}.jpg`,c.id])}
