 await run('INSERT OR IGNORE INTO servicos(id,nome,descricao,preco,ativo) VALUES(3,?,?,?,1)',['Premium','Completa + aspiração detalhada + cera + acabamento de pneus',100]);
 await run('UPDATE servicos SET nome=?,descricao=?,preco=70,ativo=1 WHERE id=1',['Express','Lavagem externa, rodas e pneus']);
 await run('UPDATE servicos SET ativo=0 WHERE id=2');
