async function saveSession(w,e,d={}){await run('INSERT OR REPLACE INTO sessoes(whatsapp,etapa,dados) VALUES(?,?,?)',[w,e,JSON.stringify(d)])} async function session(w){const r=await get('SELECT * FROM sessoes WHERE whatsapp=?',[w]);return r?{etapa:r.etapa,dados:JSON.parse(r.dados||'{}')}:null} async function clearSession(w){await run('DELETE FROM sessoes WHERE whatsapp=?',[w])}
async function servicesText(){const s=await all('SELECT * FROM servicos WHERE ativo=1 ORDER BY id');return s.map((x,i)=>`${i+1}️⃣ *${x.nome.toUpperCase()}* — ${brl(x.preco)}\n${x.descricao}`).join('\n\n')}
function cleanProfileName(value){return String(value||'').replace(/[\r\n\t]+/g,' ').replace(/\s{2,}/g,' ').trim().slice(0,80)}
function parseVehicle(value){
 const text=String(value||'').replace(/[\r\n\t]+/g,' ').replace(/\s{2,}/g,' ').trim();
 const colors=['azul marinho','azul claro','azul escuro','verde claro','verde escuro','cinza claro','cinza escuro','prata','preto','preta','branco','branca','cinza','vermelho','vermelha','azul','verde','amarelo','amarela','marrom','bege','dourado','dourada','laranja','roxo','roxa','vinho','grafite'];
 const lower=text.toLocaleLowerCase('pt-BR');
 const color=colors.find(x=>lower.endsWith(` ${x}`));
 if(color)return {modelo:text.slice(0,-color.length).trim(),cor:text.slice(-color.length).trim()};
 const split=text.lastIndexOf(' ');
 return split>0?{modelo:text.slice(0,split).trim(),cor:text.slice(split+1).trim()}:{modelo:text,cor:'Não informada'};
}
