 if(!s){if(t==='1'){await send(to,'🧽 *ESCOLHA SUA LAVAGEM*\n\n'+await servicesText()+'\n\nDigite 1 ou 2.');return saveSession(w,'servico')}; if(t==='2'){await send(to,'💰 *SERVIÇOS E PREÇOS*\n\n'+await servicesText()+'\n\nDigite *menu* para voltar.');return}; if(t==='3'){const c=await get('SELECT * FROM clientes WHERE whatsapp=?',[w]); if(!c)return send(to,'Você ainda não possui agendamentos. Digite *menu* para começar.'); const a=await all(`SELECT a.*,s.nome,v.modelo,v.cor FROM agendamentos a JOIN servicos s ON s.id=a.servico_id JOIN veiculos v ON v.id=a.veiculo_id WHERE a.cliente_id=? ORDER BY a.data DESC,a.horario DESC LIMIT 10`,[c.id]); return send(to,a.length?'📅 *MEUS AGENDAMENTOS*\n\n'+a.map(x=>`#${x.id} • ${x.data} ${x.horario}\n🚘 ${x.modelo} — ${x.cor}\n🧽 ${x.nome}\n📌 Lavagem: ${x.status}\n💳 Pagamento: ${paymentLabel(x)}`).join('\n\n'):'Nenhum agendamento encontrado.')}; if(t==='4'){const c=await get('SELECT * FROM clientes WHERE whatsapp=?',[w]);const v=c?await all('SELECT * FROM veiculos WHERE cliente_id=?',[c.id]):[];return send(to,v.length?'🚘 *MEUS VEÍCULOS*\n\n'+v.map((x,i)=>`${i+1}️⃣ ${x.modelo} — ${x.cor}`).join('\n'):'Nenhum veículo cadastrado ainda.')}; if(t==='5')return send(to,'☎️ Atendimento Harmony Car Wash.\nEnvie sua dúvida e nossa equipe responderá assim que possível.'); return menu(to,customer?.nome||automaticName)}
 if(s.etapa==='servico'){const active=await all('SELECT * FROM servicos WHERE ativo=1 ORDER BY id'),sv=active[Number(t)-1];if(!sv)return send(to,'Escolha 1 ou 2.');const c=await get('SELECT * FROM clientes WHERE whatsapp=?',[w]);if(!c){if(automaticName){await saveSession(w,'casa',{servicoId:sv.id,nome:automaticName,nomeWhatsapp:automaticName});return send(to,`Olá, *${automaticName}*! 👋\n\n🏠 Qual é o *número da sua casa*?\nExemplo: 58`)}await saveSession(w,'nome',{servicoId:sv.id});return send(to,'👤 Não consegui identificar o nome do seu perfil. Qual é o seu *nome*?')};const vs=await all('SELECT * FROM veiculos WHERE cliente_id=?',[c.id]);if(vs.length){await saveSession(w,'veiculo_existente',{servicoId:sv.id,veiculos:vs.map(x=>x.id)});return send(to,'🚘 Qual veículo vamos lavar?\n\n'+vs.map((x,i)=>`${i+1}️⃣ ${x.modelo} — ${x.cor}`).join('\n')+`\n${vs.length+1}️⃣ Cadastrar outro veículo`)} await saveSession(w,'veiculo',{servicoId:sv.id,clienteId:c.id});return send(to,'🚘 Qual é o *modelo e a cor* do seu veículo?\nExemplo: Onix branco')}
 if(s.etapa==='nome'){s.dados.nome=t;await saveSession(w,'casa',s.dados);return send(to,'🏠 Qual é o *número da sua casa*?\nExemplo: 58')}
 if(s.etapa==='casa'){const r=await run('INSERT INTO clientes(whatsapp,nome,nome_whatsapp,nome_manual,casa) VALUES(?,?,?,?,?)',[w,s.dados.nome,s.dados.nomeWhatsapp||automaticName||s.dados.nome,0,t]);s.dados.clienteId=r.lastID;await saveSession(w,'veiculo',s.dados);return send(to,'🚘 Qual é o *modelo e a cor* do seu veículo?\nExemplo: Onix branco')}
