const GEMINI_AI_SCHEMA={type:'object',properties:{intent:{type:'string',enum:['booking','prices','appointments','vehicles','support','cancel','greeting']},reply:{type:'string'},service:{type:'string',nullable:true,enum:['express','premium']},house:{type:'string',nullable:true},vehicle_model:{type:'string',nullable:true},vehicle_color:{type:'string',nullable:true},date:{type:'string',nullable:true},time:{type:'string',nullable:true},payment:{type:'string',nullable:true,enum:['now','after']},confirmed:{type:'boolean'}},required:['intent','reply','service','house','vehicle_model','vehicle_color','date','time','payment','confirmed']};
function aiMode(){return ['openai','gemini'].includes(settings.ai_provider)?settings.ai_provider:'menu'}
function jsonFromAI(value){const raw=String(value||'').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');const start=raw.indexOf('{'),end=raw.lastIndexOf('}');if(start<0||end<start)throw Error('A IA não retornou JSON válido');return JSON.parse(raw.slice(start,end+1))}
async function callOpenAI(system,user){if(!settings.openai_api_key)throw Error('Chave da OpenAI não configurada');const model=settings.openai_model||'gpt-5-mini';const body={model,instructions:system,input:user,text:{format:{type:'json_schema',name:'harmony_atendimento',strict:true,schema:AI_SCHEMA}}};const d=(await axios.post('https://api.openai.com/v1/responses',body,{headers:{Authorization:`Bearer ${settings.openai_api_key}`,'Content-Type':'application/json'},timeout:45000})).data;const text=d.output_text||d.output?.flatMap(x=>x.content||[]).find(x=>x.type==='output_text')?.text;if(!text)throw Error('Resposta vazia da OpenAI');return jsonFromAI(text)}
async function callGemini(system,user){if(!settings.gemini_api_key)throw Error('Chave do Gemini não configurada');const model=settings.gemini_model||'gemini-3.5-flash-lite';const body={systemInstruction:{parts:[{text:system}]},contents:[{role:'user',parts:[{text:user}]}],generationConfig:{responseMimeType:'application/json',responseSchema:GEMINI_AI_SCHEMA,temperature:0.2}};const d=(await axios.post(`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`,body,{headers:{'x-goog-api-key':settings.gemini_api_key,'Content-Type':'application/json'},timeout:45000})).data;const text=d.candidates?.[0]?.content?.parts?.map(x=>x.text||'').join('');if(!text)throw Error('Resposta vazia do Gemini');return jsonFromAI(text)}
async function askSelectedAI(system,user){const primary=aiMode(),providers=[primary,primary==='openai'?'gemini':'openai'];let last;for(const provider of providers){try{return provider==='openai'?await callOpenAI(system,user):await callGemini(system,user)}catch(e){last=e;console.error(`IA ${provider} indisponível`,e.response?.data||e.message)}}throw last||Error('Nenhuma IA configurada')}
async function customerMemory(customer){if(!customer)return [];return all(`SELECT a.data,a.horario,a.forma_pagamento,a.avaliacao,s.nome servico,v.modelo,v.cor FROM agendamentos a JOIN servicos s ON s.id=a.servico_id JOIN veiculos v ON v.id=a.veiculo_id WHERE a.cliente_id=? AND a.status<>'cancelado' ORDER BY a.id DESC LIMIT 5`,[customer.id])}
async function aiSystemPrompt(customer,vehicles,data){const active=await all('SELECT id,nome,descricao,preco FROM servicos WHERE ativo=1 ORDER BY id'),history=await customerMemory(customer);let free=[];if(data.data&&/^\d{4}-\d{2}-\d{2}$/.test(data.data))free=await availableSlots(data.data);return `Você é a assistente virtual do André no Harmony Car Wash, dentro do condomínio Harmony Residence. Fale em português do Brasil, de forma curta, próxima e educada, como atendimento entre vizinhos. Use o nome do cliente e a palavra vizinho de vez em quando, sem repetir em toda frase. Seja transparente: você é a assistente do André, nunca finja ser o André. Conduza o agendamento, mas apenas extraia dados; o código do sistema faz perguntas obrigatórias, valida agenda, cobra e confirma. Nunca diga que reservou, confirmou, salvou, cobrou ou concluiu um agendamento. Nunca invente preço, horário, pagamento ou disponibilidade. Devolva SOMENTE JSON compatível com o esquema recebido. Hoje é ${isoBahia()} no fuso America/Bahia. Serviços oficiais: ${JSON.stringify(active)}. Horários padrão: ${slots.join(', ')}. Cliente salvo: ${JSON.stringify(customer?{nome:customer.nome,casa:customer.casa,observacoes:customer.observacoes||''}:null)}. Veículos salvos: ${JSON.stringify(vehicles.map(v=>({modelo:v.modelo,cor:v.cor})))}. Histórico recente confirmado: ${JSON.stringify(history)}. Dados já coletados: ${JSON.stringify(data)}. Horários livres da data escolhida: ${JSON.stringify(free)}. Se o cliente disser que quer repetir o último serviço, use o histórico recente. Datas relativas como hoje e amanhã devem virar AAAA-MM-DD. Se pedir preços use intent prices; histórico, appointments; veículos, vehicles; humano, support; cancelar, cancel. Só marque confirmed=true quando ele responder claramente ao resumo final. Não solicite CPF; o sistema cuida disso.`}
async function sendAIText(to,text,withImage=false){if(withImage){const image=await nextMenuImage();if(sock&&connected&&image)return sock.sendMessage(to,{image:fs.readFileSync(image),caption:text})}return send(to,text)}
function normalizeRequestedTime(value){const text=String(value||'').toLocaleLowerCase('pt-BR').trim();const m=text.match(/(?:^|\s)(\d{1,2})(?:[h:]?(\d{2}))?(?:\s*(?:h|hora|horas))?(?:$|\s)/);if(!m)return '';const hour=Number(m[1]),minute=Number(m[2]||0);if(hour>23||minute>59)return '';return `${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')}`}
function directPaymentChoice(text){const t=String(text||'').trim().toLowerCase();if(t==='1'||/^1[).:-]?\s*(pix|pagar agora)?$/i.test(t))return PAY_NOW;if(t==='2'||/^2[).:-]?\s*(pagar depois|depois)?$/i.test(t))return PAY_AFTER;return ''}
function directConfirmationChoice(text){return /^(?:sim|confirmar|confirmo|confirmado|pode confirmar|está certo|esta certo)$/i.test(String(text||'').trim())}
function asksForAvailableTimes(value){return /qual\s+hor[aá]rio|quais?\s+hor[aá]rios|hor[aá]rio\s+(?:tem|dispon|livre)|tem\s+hor[aá]rio/i.test(String(value||''))}
function timeOptionsText(free,date){return free.length?`⏰ Horários livres para ${displayDate(date)}:\n\n${free.map(x=>`• ${x}`).join('\n')}\n\nQual você prefere, vizinho?`:`🚗 Não há horários livres para ${displayDate(date)}. Posso procurar outro dia?`}
function aiMissingQuestion(d,free=[]){if(!d.servicoId)return 'Você prefere a lavagem *Express por R$ 70* ou *Premium por R$ 100*?';if(!d.casa)return '🏠 Qual é o número da sua casa?';if(!d.modelo||!d.cor)return '🚘 Qual é o modelo e a cor do veículo? Exemplo: Onix branco.';if(!d.data)return '📅 Para qual dia deseja agendar? Pode responder hoje, amanhã ou informar a data.';if(!d.horario)return free.length?timeOptionsText(free,d.data):'⏰ Qual horário você prefere?';if(!d.formaPagamento)return '💳 Como prefere pagar, vizinho?\n\n1️⃣ Pagar agora pelo PIX\n2️⃣ Pagar depois da lavagem';return ''}
async function aiSummary(d){const sv=await get('SELECT nome,preco FROM servicos WHERE id=?',[d.servicoId]);return `Confirma este agendamento?\n\n🧽 ${sv.nome} — ${brl(sv.preco)}\n🏠 Casa ${d.casa}\n🚘 ${d.modelo} — ${d.cor}\n📅 ${displayDate(d.data)} às ${d.horario}\n💳 ${d.formaPagamento===PAY_NOW?'Pagar agora pelo PIX':'Pagar após a lavagem'}\n\nResponda *confirmar* ou diga o que deseja alterar.`}
async function completeAIBooking(to,w,d,customer,automaticName){if(!customer){const name=automaticName||'Cliente';const r=await run('INSERT INTO clientes(whatsapp,nome,nome_whatsapp,nome_manual,casa) VALUES(?,?,?,?,?)',[w,name,automaticName||name,0,d.casa]);customer=await get('SELECT * FROM clientes WHERE id=?',[r.lastID])}else if(d.casa&&d.casa!==customer.casa){await run('UPDATE clientes SET casa=? WHERE id=?',[d.casa,customer.id]);customer.casa=d.casa}let vehicle=await get('SELECT * FROM veiculos WHERE cliente_id=? AND lower(modelo)=lower(?) AND lower(cor)=lower(?)',[customer.id,d.modelo,d.cor]);if(!vehicle){const r=await run('INSERT INTO veiculos(cliente_id,modelo,cor) VALUES(?,?,?)',[customer.id,d.modelo,d.cor]);vehicle={id:r.lastID}}d.veiculoId=vehicle.id;d.paymentProvider=settings.payment_provider==='misticpay'?'misticpay':'mercadopago';if(d.paymentProvider==='misticpay'&&!customer.documento){await saveSession(w,'ai_documento',d);return send(to,'💳 Para gerar o PIX pela MisticPay, informe o CPF do pagador com 11 dígitos. Esse dado será solicitado somente uma vez.')}const free=await availableSlots(d.data);if(!free.includes(d.horario)){d.horario='';d.awaitingConfirmation=false;await saveSession(w,'ai',d);return send(to,`Esse horário acabou de ser ocupado. Horários livres em ${displayDate(d.data)}: ${free.join(', ')||'nenhum'}. Qual você prefere?`)}return createBooking(to,w,d,customer)}
async function handleAI(to,text,profileName=''){const w=num(to),t=String(text||'').trim(),automaticName=cleanProfileName(profileName);if(!t)return;let customer=await get('SELECT * FROM clientes WHERE whatsapp=?',[w]);if(customer&&automaticName){await run('UPDATE clientes SET nome_whatsapp=?,nome=CASE WHEN COALESCE(nome_manual,0)=0 THEN ? ELSE nome END WHERE id=?',[automaticName,automaticName,customer.id]);customer=await get('SELECT * FROM clientes WHERE id=?',[customer.id])}let s=await session(w);if(s?.etapa==='avaliacao'){const score=Number((t.match(/[1-5]/)||[])[0]);if(!score)return send(to,'⭐ Me diga uma nota de 1 a 5, vizinho.');await run('UPDATE agendamentos SET avaliacao=?,comentario_avaliacao=? WHERE id=?',[score,t,s.dados.agendamentoId]);await clearSession(w);return send(to,`Obrigado pela avaliação, vizinho! ${'⭐'.repeat(score)} Quando precisar, é só chamar. 🚗✨`)}if(s?.etapa==='ai_documento'){const doc=t.replace(/\D/g,'');if(doc.length!==11)return send(to,'CPF inválido. Envie os 11 dígitos, somente números.');if(!customer){const r=await run('INSERT INTO clientes(whatsapp,nome,nome_whatsapp,nome_manual,casa,documento) VALUES(?,?,?,?,?,?)',[w,automaticName||'Cliente',automaticName||'Cliente',0,s.dados.casa,doc]);customer=await get('SELECT * FROM clientes WHERE id=?',[r.lastID])}else{await run('UPDATE clientes SET documento=? WHERE id=?',[doc,customer.id]);customer.documento=doc}return completeAIBooking(to,w,s.dados,customer,automaticName)}if(!s||s.etapa!=='ai')s={etapa:'ai',dados:{}};const d=s.dados||{},wasEmpty=!Object.keys(d).length,vehicles=customer?await all('SELECT * FROM veiculos WHERE cliente_id=?',[customer.id]):[];let result;const directPayment=directPaymentChoice(t),directConfirmation=d.awaitingConfirmation&&directConfirmationChoice(t);try{result=directConfirmation?{intent:'booking',reply:'',service:null,house:null,vehicle_model:null,vehicle_color:null,date:null,time:null,payment:null,confirmed:true}:directPayment?{intent:'booking',reply:'',service:null,house:null,vehicle_model:null,vehicle_color:null,date:null,time:null,payment:directPayment===PAY_NOW?'now':'after',confirmed:false}:await askSelectedAI(await aiSystemPrompt(customer,vehicles,d),t)}catch(e){console.error('IA HARMONY',e.response?.data||e.message);await send(to,'⚠️ A assistente está demorando para responder. Seus dados foram preservados. Digite continuar ou menu.');return}if(result.intent==='cancel'){await clearSession(w);return send(to,'Tudo certo, vizinho. O atendimento foi cancelado. Quando precisar, é só chamar. 🚗✨')}if(result.intent==='prices')return send(to,'💰 *SERVIÇOS E PREÇOS*\n\n'+await servicesText()+'\n\nSe quiser, posso fazer seu agendamento por aqui.');if(result.intent==='appointments'){if(!customer)return send(to,'Você ainda não possui agendamentos. Posso fazer o primeiro agora.');const a=await all(`SELECT a.*,s.nome,v.modelo,v.cor FROM agendamentos a JOIN servicos s ON s.id=a.servico_id JOIN veiculos v ON v.id=a.veiculo_id WHERE a.cliente_id=? ORDER BY a.data DESC,a.horario DESC LIMIT 10`,[customer.id]);return send(to,a.length?'📅 *SEUS AGENDAMENTOS*\n\n'+a.map(x=>`#${x.id} • ${displayDate(x.data)} ${x.horario}\n🚘 ${x.modelo} — ${x.cor}\n🧽 ${x.nome}\n📌 ${x.status}`).join('\n\n'):'Nenhum agendamento encontrado.')}if(result.intent==='vehicles')return send(to,vehicles.length?'🚘 *SEUS VEÍCULOS*\n\n'+vehicles.map(x=>`${x.modelo} — ${x.cor}`).join('\n'):'Você ainda não possui veículo cadastrado.');if(result.intent==='support')return send(to,'☎️ Vou avisar o André que você precisa de atendimento. Pode enviar sua dúvida por aqui.');const active=await all('SELECT * FROM servicos WHERE ativo=1 ORDER BY id');if(result.service)d.servicoId=active.find(x=>x.nome.toLowerCase()===String(result.service).toLowerCase())?.id||d.servicoId;if(result.house)d.casa=String(result.house).trim().slice(0,20);else if(!d.casa&&customer?.casa)d.casa=customer.casa;if(result.vehicle_model)d.modelo=String(result.vehicle_model).trim().slice(0,80);if(result.vehicle_color)d.cor=String(result.vehicle_color).trim().slice(0,40);if(result.date&&/^\d{4}-\d{2}-\d{2}$/.test(result.date)&&result.date>=isoBahia())d.data=result.date;const requestedTime=normalizeRequestedTime(t);if(result.time&&slots.includes(result.time))d.horario=result.time;else if(requestedTime&&slots.includes(requestedTime))d.horario=requestedTime;if(result.payment)d.formaPagamento=result.payment==='now'?PAY_NOW:PAY_AFTER;const freeForDate=d.data?await availableSlots(d.data):[];if(d.data&&!d.horario&&(asksForAvailableTimes(t)||requestedTime&&!slots.includes(requestedTime)))return send(to,requestedTime&&!slots.includes(requestedTime)?`⏰ O horário ${requestedTime} não está na agenda.\n\n${timeOptionsText(freeForDate,d.data)}`:timeOptionsText(freeForDate,d.data));if(d.data&&d.horario){if(!freeForDate.includes(d.horario)){d.horario='';d.awaitingConfirmation=false;await saveSession(w,'ai',d);return send(to,timeOptionsText(freeForDate,d.data))}}const complete=d.servicoId&&d.casa&&d.modelo&&d.cor&&d.data&&d.horario&&d.formaPagamento;if(complete&&result.confirmed&&d.awaitingConfirmation)return completeAIBooking(to,w,d,customer,automaticName);if(complete){d.awaitingConfirmation=true;await saveSession(w,'ai',d);return send(to,await aiSummary(d))}d.awaitingConfirmation=false;await saveSession(w,'ai',d);const question=aiMissingQuestion(d,freeForDate),name=customer?.nome||automaticName;if(wasEmpty&&result.intent==='greeting')return sendAIText(to,`Olá${name?`, *${name}*`:''}! Tudo certo, vizinho? 😊\nAqui é a assistente do André, do Harmony Car Wash.\n\n${question}`,true);return send(to,question)}
async function handle(to,text,profileName=''){const mode=aiMode();if(mode==='menu')return handleLegacy(to,text,profileName);return handleAI(to,text,profileName)}
async function askDate(to,w,d){await saveSession(w,'data',d);await send(to,'📅 *Quando você deseja lavar o veículo?*\n\n1️⃣ Hoje\n2️⃣ Amanhã\n3️⃣ Escolher outra data\n0️⃣ Voltar')}
async function selectBookingDate(to,w,s,date){if(date<isoBahia())return send(to,'⚠️ Escolha uma data de hoje em diante.');const parsed=new Date(date+'T12:00:00-03:00');if(Number.isNaN(parsed.getTime())||isoBahia(parsed)!==date)return send(to,'⚠️ Essa data não existe. Escolha outra data.');s.dados.data=date;const busy=(await all('SELECT horario FROM agendamentos WHERE data=? AND status<>"cancelado"',[date])).map(x=>x.horario);const free=slots.filter(x=>!busy.includes(x));if(!free.length){await saveSession(w,'data',s.dados);return send(to,'🚗 Agenda lotada nessa data.\n\nEscolha novamente:\n1️⃣ Hoje\n2️⃣ Amanhã\n3️⃣ Outra data')}s.dados.free=free;await saveSession(w,'horario',s.dados);return send(to,'⏰ *HORÁRIOS DISPONÍVEIS*\n\n'+free.map((x,i)=>`${i+1}️⃣ ${x}`).join('\n')+'\n\nEscolha uma opção.')}
function paymentLabel(a){if(a.pagamento_status==='paid')return '✅ Pago';if(a.pagamento_status==='expired')return '⌛ PIX expirado';if(a.forma_pagamento===PAY_AFTER&&a.status!=='finalizado')return '🕒 Após o serviço';return '⏳ Pendente'}
async function createBooking(to,w,d,c){const sv=await get('SELECT * FROM servicos WHERE id=?',[d.servicoId]);await run('DELETE FROM agendamentos WHERE data=? AND horario=? AND status="cancelado"',[d.data,d.horario]);let ag;const after=d.formaPagamento===PAY_AFTER,provider=d.paymentProvider==='misticpay'?'misticpay':'mercadopago';try{ag=await run('INSERT INTO agendamentos(cliente_id,veiculo_id,servico_id,data,horario,status,pagamento_status,forma_pagamento,payment_provider,autoriza_divulgacao) VALUES(?,?,?,?,?,?,?,?,?,1)',[c.id,d.veiculoId,d.servicoId,d.data,d.horario,after?'agendado':'aguardando_pagamento',after?'pending_after_service':'pending',d.formaPagamento,provider])}catch(e){await clearSession(w);await send(to,'⚠️ Esse horário acabou de ser reservado. Digite *menu* e escolha outro.');return}await clearSession(w);const resumo=`🧾 *RESERVA #${ag.lastID}*\n🏠 Casa ${c.casa}\n📅 ${d.data} às ${d.horario}\n🧽 ${sv.nome}\n💰 ${brl(sv.preco)}`;if(after){await send(to,`${resumo}\n\n✅ *AGENDAMENTO CONFIRMADO!*\nPagamento escolhido: após a lavagem. O PIX será enviado quando o serviço for finalizado.`);await notifyWasherBooking(ag.lastID);io.emit('refresh');return}await send(to,`${resumo}\n\n⏳ Gerando PIX...`);await generatePix(ag.lastID,to,true)}
async function generatePix(id,to,expires){
 const a=await booking(id);
 try{
  let pid,code;
  if(a.payment_provider==='misticpay'){
   if(!settings.misticpay_client_id||!settings.misticpay_client_secret)throw Error('Configure as credenciais da MisticPay no painel');
   if(!a.documento)throw Error('CPF do pagador não cadastrado para a MisticPay');
   const body={amount:Number(a.preco),payerName:a.nome,payerDocument:String(a.documento).replace(/\D/g,''),transactionId:`harmony_${id}_${Date.now()}`,description:`Harmony Car Wash #${id}`};
   if(settings.base_url)body.projectWebhook=`${settings.base_url}/api/webhooks/misticpay`;
   const r=await axios.post('https://api.misticpay.com/api/transactions/create',body,{auth:{username:settings.misticpay_client_id,password:settings.misticpay_client_secret},headers:{'Content-Type':'application/json'},timeout:30000});
   pid=r.data?.data?.transactionId||body.transactionId;code=r.data?.data?.copyPaste;
   if(!pid||!code)throw Error('Resposta da MisticPay incompleta');
  }else{
   if(!settings.mercadopago_access_token)throw Error('Configure o Access Token do Mercado Pago no painel');
   const expiration=new Date(Date.now()+(expires?10:1440)*60000).toISOString();
   const body={transaction_amount:Number(a.preco),description:`Harmony Car Wash #${id}`,payment_method_id:'pix',external_reference:`harmony_${id}`,date_of_expiration:expiration,payer:{email:`cliente${id}@example.com`,first_name:a.nome}};
   if(settings.base_url)body.notification_url=`${settings.base_url}/api/webhooks/mercadopago`;
   const r=await axios.post('https://api.mercadopago.com/v1/payments',body,{headers:{'Content-Type':'application/json','Authorization':`Bearer ${settings.mercadopago_access_token}`,'X-Idempotency-Key':`harmony-${id}-${Date.now()}`},timeout:30000});
   pid=r.data?.id;code=r.data?.point_of_interaction?.transaction_data?.qr_code;
   if(!pid||!code)throw Error('Resposta do Mercado Pago incompleta');
  }
  const clean=String(code).replace(/[\r\n\t]/g,'');await run('UPDATE agendamentos SET payment_id=?,pix_code=?,payment_created_at=datetime("now") WHERE id=?',[String(pid),clean,id]);
  try{await send(to,'📋 *PIX Copia e Cola:*');await send(to,clean);await send(to,expires?'⏳ O horário ficará reservado por 10 minutos enquanto aguardamos o pagamento.':'✅ A lavagem foi concluída. Assim que o PIX for confirmado, o pagamento aparecerá como recebido.')}catch(e){console.error('ENVIO PIX',e.message)}
  pollPayment(id,pid,to,expires)
 }catch(e){await run('UPDATE agendamentos SET pagamento_status="error" WHERE id=?',[id]);if(expires)await run('UPDATE agendamentos SET status="cancelado" WHERE id=?',[id]);try{await send(to,expires?'❌ Não foi possível gerar o PIX e o horário foi liberado. Digite *menu* para tentar novamente.':'❌ A lavagem foi concluída, mas não conseguimos gerar o PIX. Nossa equipe fará a cobrança manualmente.')}catch(_){}console.error('PAGAMENTO PIX',e.response?.data||e.message)}
}
async function requestRating(to,id){await saveSession(num(to),'avaliacao',{agendamentoId:id});return send(to,'⭐ Vizinho, depois que receber as fotos, pode dar uma nota de 1 a 5 para o atendimento?')}
async function checkPayment(id,pid,to){try{const a=await booking(id);let paid=false;if(a.payment_provider==='misticpay'){if(!settings.misticpay_client_id||!settings.misticpay_client_secret)return false;const d=(await axios.post('https://api.misticpay.com/api/transactions/check',{transactionId:pid},{auth:{username:settings.misticpay_client_id,password:settings.misticpay_client_secret},headers:{'Content-Type':'application/json'},timeout:15000})).data;paid=String(d?.transaction?.transactionState||'').toUpperCase()==='COMPLETO'}else{if(!settings.mercadopago_access_token)return false;const d=(await axios.get(`https://api.mercadopago.com/v1/payments/${encodeURIComponent(pid)}`,{headers:{'Authorization':`Bearer ${settings.mercadopago_access_token}`},timeout:15000})).data;paid=String(d?.status||'').toLowerCase()==='approved'}if(!paid)return false;const wasFinalized=a.status==='finalizado';await run('UPDATE agendamentos SET pagamento_status="paid",status=? WHERE id=?',[wasFinalized?'finalizado':'agendado',id]);if(wasFinalized){try{await send(to,`✅ *PAGAMENTO CONFIRMADO!*\n\nObrigado pelo pagamento da lavagem #${id}, vizinho! Foi um prazer cuidar do seu carro. 🚗✨`)}catch(_){}await requestRating(to,id)}else{try{await send(to,`✅ *PAGAMENTO CONFIRMADO!*\n\nPagamento da lavagem #${id} recebido com sucesso. Até a lavagem, vizinho! 🚗✨`)}catch(_){}await notifyWasherBooking(id)}io.emit('refresh');return true}catch(e){return false}}
function pollPayment(id,pid,to,expires=false){let tries=0;const timer=setInterval(async()=>{if(await checkPayment(id,pid,to))return clearInterval(timer);if(++tries>=60){clearInterval(timer);if(expires){const a=await booking(id);if(a&&a.pagamento_status!=='paid'&&a.status==='aguardando_pagamento'){await run('UPDATE agendamentos SET pagamento_status="expired",status="cancelado" WHERE id=?',[id]);await send(to,`⌛ O PIX da reserva #${id} expirou e o horário foi liberado. Digite *menu* para fazer um novo agendamento.`);io.emit('refresh')}}}},10000)}
function washerNumber(){return String(settings.lavador_whatsapp||'').replace(/\D/g,'')}
function displayDate(date){return String(date||'').split('-').reverse().join('/')}
function washerBookingText(a,prefix){return `${prefix}\n\n🧾 Agendamento #${a.id}\n👤 ${a.nome}\n🏠 Casa ${a.casa}\n📅 ${displayDate(a.data)} às ${a.horario}\n🚘 ${a.modelo} — ${a.cor}\n🧽 ${a.servico}`}
async function notifyWasherBooking(id){const number=washerNumber(),a=await booking(id);if(!number||!a||!connected||!sock||a.lavador_notificado||!['agendado','indo','lavando'].includes(a.status))return false;try{await send(jid(number),washerBookingText(a,'🔔 *NOVO AGENDAMENTO CONFIRMADO*'));await run('UPDATE agendamentos SET lavador_notificado=1 WHERE id=?',[id]);return true}catch(e){console.error('AVISO LAVADOR',e.message);return false}}
async function checkWasherReminders(){
 const number=washerNumber();if(!number||!connected||!sock)return;
 const pending=await all(`SELECT id FROM agendamentos WHERE status='agendado' AND lembrete_lavador_enviado=0 AND data=?`,[isoBahia()]);
 const now=Date.now();
 for(const row of pending){const a=await booking(row.id);if(!a)continue;const appointment=new Date(`${a.data}T${a.horario}:00-03:00`).getTime(),minutes=(appointment-now)/60000;if(minutes>15||minutes<0)continue;try{await send(jid(number),washerBookingText(a,'⏰ *FALTAM 15 MINUTOS PARA A LAVAGEM*'));await run('UPDATE agendamentos SET lembrete_lavador_enviado=1 WHERE id=?',[a.id])}catch(e){console.error('LEMBRETE LAVADOR',e.message)}}
 const unnotified=await all(`SELECT id FROM agendamentos WHERE lavador_notificado=0 AND status='agendado' ORDER BY id LIMIT 50`);for(const row of unnotified)await notifyWasherBooking(row.id)
}
function privateGroup(){return String(settings.whatsapp_private_group_jid||settings.whatsapp_group_jid||'').trim()}
function announcementGroups(){let list=[];try{const raw=JSON.parse(String(settings.whatsapp_group_jids||'[]'));if(Array.isArray(raw))list=raw}catch{}if(!list.length&&settings.whatsapp_group_jid)list=[settings.whatsapp_group_jid];return [...new Set(list.map(x=>String(x||'').trim()).filter(Boolean))]}
function groupEnabled(){return connected&&sock&&settings.publicar_grupo==='1'&&announcementGroups().length>0}
function bookingLink(){const configured=String(settings.whatsapp_public_number||'').replace(/\D/g,'');const own=num(sock?.user?.id);const phone=configured||own;return phone?`https://wa.me/${phone}?text=${encodeURIComponent('Olá, quero agendar uma lavagem')}`:''}
async function availableSlots(date){const busy=(await all('SELECT horario FROM agendamentos WHERE data=? AND status<>"cancelado"',[date])).map(x=>x.horario);return slots.filter(x=>!busy.includes(x))}
async function nextAvailableDate(start=isoBahia()){for(let i=0;i<30;i++){const date=addDays(start,i),free=await availableSlots(date);if(free.length)return {date,free}}return null}
async function currentCampaign(date=isoBahia()){const year=Number(date.slice(0,4));for(const c of await all('SELECT * FROM campanhas WHERE ativo=1'))for(const y of [year,year+1]){const target=campaignDates(y)[c.id];if(target&&date>=addDays(target,-Number(c.antecedencia||0))&&date<=target)return {...c,target}}return null}
async function sendGroupMessage(text,imagePath){const privateOnly=String(imagePath||'').endsWith('-grupo.jpg'),groups=privateOnly?[privateGroup()]:announcementGroups();if(!connected||!sock||!groups.filter(Boolean).length||(!privateOnly&&!groupEnabled()))return false;const content=imagePath&&fs.existsSync(imagePath)?{image:fs.readFileSync(imagePath),caption:text}:{text};let sent=0;for(const group of groups.filter(Boolean)){try{await sock.sendMessage(group,content);sent++}catch(e){console.error('ENVIO GRUPO',group,e.message)}}return sent>0}
async function sendPrivateGroupMessage(text,imagePath){const group=privateGroup();if(!connected||!sock||!group)return false;const content=imagePath&&fs.existsSync(imagePath)?{image:fs.readFileSync(imagePath),caption:text}:{text};try{await sock.sendMessage(group,content);return true}catch(e){console.error('ENVIO GRUPO PRIVADO',e.message);return false}}
function dailyAdImage(date){const day=Math.floor(new Date(`${date}T12:00:00-03:00`).getTime()/86400000),slot=(Math.abs(day)%5)+1,file=path.join(AD_DIR,`anuncio-${String(slot).padStart(2,'0')}.jpg`);return fs.existsSync(file)?file:null}
async function sendScheduledAd(slot,options={}){const date=isoBahia(),key=`anuncio:${date}:${slot}`;if(!options.force&&await get('SELECT 1 FROM envios_automaticos WHERE chave=?',[key]))return {sent:false,reason:'already_sent'};if(!groupEnabled())return {sent:false,reason:'group_not_configured'};const next=await nextAvailableDate(date);if(!next)return {sent:false,reason:'no_availability'};const campaign=await currentCampaign(date);const intro=campaign?.texto||(slot==='07'?'☀️ Bom dia, Harmony Residence! A agenda do Harmony Car Wash está aberta.':'🚗 Ainda quer deixar seu carro limpo hoje? Confira os horários disponíveis.');const when=next.date===date?'hoje':`em ${next.date.split('-').reverse().join('/')}`;const free=next.free.join(', ');const link=bookingLink();const text=`${intro}\n\n📅 Próxima disponibilidade: *${when}*\n⏰ Horários: ${free}\n\nSeu carro limpo sem sair de casa. 🏠${link?`\n\n👉 Agende aqui: ${link}`:''}`;const campaignImage=campaign?.imagem?path.join(CAMPAIGN_DIR,path.basename(campaign.imagem)):null,image=campaignImage&&fs.existsSync(campaignImage)?campaignImage:dailyAdImage(date);if(await sendGroupMessage(text,image)){await run('INSERT OR IGNORE INTO envios_automaticos(chave) VALUES(?)',[key]);return {sent:true,slot,text}}return {sent:false,reason:'send_failed'}}
async function resumePendingPayments(){const pending=await all('SELECT a.*,c.whatsapp FROM agendamentos a JOIN clientes c ON c.id=a.cliente_id WHERE a.payment_id IS NOT NULL AND a.pagamento_status NOT IN ("paid","expired")');for(const a of pending){const paid=await checkPayment(a.id,a.payment_id,jid(a.whatsapp));if(!paid&&a.forma_pagamento===PAY_NOW&&a.status==='aguardando_pagamento'){const age=Date.now()-new Date(String(a.payment_created_at||a.created_at).replace(' ','T')+'Z').getTime();if(age>=10*60*1000){await run('UPDATE agendamentos SET pagamento_status="expired",status="cancelado" WHERE id=?',[a.id]);await send(jid(a.whatsapp),`⌛ O PIX da reserva #${a.id} expirou e o horário foi liberado.`);io.emit('refresh')}}}}
function startAutomations(){cron.schedule('0 7 * * *',()=>sendScheduledAd('07').catch(console.error),{timezone:TZ});cron.schedule('0 12 * * *',()=>sendScheduledAd('12').catch(console.error),{timezone:TZ});setInterval(()=>{resumePendingPayments().catch(console.error);checkWasherReminders().catch(console.error)},60*1000);checkWasherReminders().catch(console.error)}
function waMarker(){return path.join(SESSION,'.harmony-session-ok')}
function waRestorable(){try{if(fs.existsSync(waMarker()))return true;const f=path.join(SESSION,'creds.json');if(!fs.existsSync(f))return false;const c=JSON.parse(fs.readFileSync(f,'utf8'));return c?.registered===true||!!(c?.me?.id||c?.me?.lid)}catch{return false}}
function emitWa(){io.emit('wa-status',{connected,status:waStatus,error:waError,qr:!!qrData})}
async function waVersion(){const fallback=[2,3000,1043857760];try{if(typeof baileys.fetchLatestWaWebVersion!=='function')return fallback;const r=await Promise.race([baileys.fetchLatestWaWebVersion(),new Promise((_,rej)=>setTimeout(()=>rej(Error('timeout versão WA Web')),12000))]);return Array.isArray(r?.version)&&r.version.length===3?r.version:fallback}catch(e){console.log('⚠️ HARMONY WA VERSION:',e.message);return fallback}}
function stopWa(){waGeneration++;if(waReconnectTimer)clearTimeout(waReconnectTimer);waReconnectTimer=null;const current=sock;sock=null;connected=false;qrData='';try{current?.end?.(new Error('reinício solicitado pelo painel'))}catch(_){}emitWa()}
function scheduleWaRestore(delay=2500){if(waReconnectTimer||!waRestorable())return;waReconnectTimer=setTimeout(()=>{waReconnectTimer=null;if(!sock&&!connected&&!waStarting)startWhatsApp({mode:'restore'}).catch(e=>console.log('❌ HARMONY WA RESTORE:',e.message))},delay)}
async function startWhatsApp(options={}){
 if(waStarting||sock)return;
 waStarting=true;const generation=++waGeneration;waStatus='INICIANDO';waError='';if(options.mode==='qr')qrData='';emitWa();
 try{
  fs.mkdirSync(SESSION,{recursive:true});
  const makeWASocket=baileys.default||baileys.makeWASocket,{state,saveCreds}=await baileys.useMultiFileAuthState(SESSION),version=await waVersion();
  const current=makeWASocket({auth:state,version,logger:pino({level:process.env.WHATSAPP_LOG_LEVEL||'silent'}),printQRInTerminal:false,browser:baileys.Browsers?.ubuntu?baileys.Browsers.ubuntu('Chrome'):['Ubuntu','Chrome','22.04.4'],markOnlineOnConnect:false,syncFullHistory:false,generateHighQualityLinkPreview:false,connectTimeoutMs:30000,defaultQueryTimeoutMs:30000,keepAliveIntervalMs:20000,retryRequestDelayMs:500});
  sock=current;waStarting=false;console.log(`🧩 HARMONY WhatsApp iniciado em modo ${options.mode||'restore'}; versão ${version.join('.')}`);
  current.ev.on('creds.update',async()=>{try{await saveCreds()}catch(e){console.log('⚠️ HARMONY SAVE CREDS:',e.message)}});
  current.ev.on('connection.update',async update=>{
   if(generation!==waGeneration||sock!==current)return;
   const {connection,lastDisconnect,qr}=update||{};
   try{
    if(qr){qrData=await QRCode.toDataURL(qr,{width:360,margin:2,errorCorrectionLevel:'M'});connected=false;waStatus='AGUARDANDO_QR';waError='';console.log('📷 HARMONY QR Code gerado');emitWa()}
    if(connection==='connecting'&&!qrData){waStatus='CONECTANDO';emitWa()}
    if(connection==='open'){await saveCreds();fs.writeFileSync(waMarker(),String(Date.now()));connected=true;qrData='';waStatus='CONECTADO';waError='';console.log('✅ HARMONY WhatsApp conectado');emitWa()}
    if(connection==='close'){
     sock=null;connected=false;qrData='';const err=lastDisconnect?.error,code=err?.output?.statusCode||err?.statusCode||err?.data?.statusCode||err?.cause?.output?.statusCode||err?.cause?.statusCode;const loggedOut=code===baileys.DisconnectReason?.loggedOut;const restart=Number(code)===515||code===baileys.DisconnectReason?.restartRequired;waError=err?.message||`código ${code||'desconhecido'}`;console.log(`🔎 HARMONY WA CLOSE code=${code||'sem-codigo'} restorable=${waRestorable()} msg=${waError}`);
     if(restart||(!loggedOut&&waRestorable())){waStatus='RECONECTANDO';emitWa();scheduleWaRestore(restart?2200:3500)}else{waStatus=loggedOut?'SESSAO_EXPIRADA':'FALHA_QR';emitWa()}
    }
   }catch(e){waStatus='ERRO';waError=e.message;console.log('❌ HARMONY WA UPDATE:',e.stack||e.message);emitWa()}
  });
  current.ev.on('messages.upsert',async ev=>{for(const m of ev.messages||[]){if(!m.message||m.key.fromMe||m.key.remoteJid?.endsWith('@g.us'))continue;const text=m.message.conversation||m.message.extendedTextMessage?.text||'';await handle(m.key.remoteJid,text,m.pushName||m.verifiedBizName||'')}});
 }catch(e){waStarting=false;sock=null;connected=false;waStatus='ERRO';waError=e.message;console.log('❌ HARMONY INICIAR WHATSAPP:',e.stack||e.message);emitWa();if(waRestorable())scheduleWaRestore(5000)}
}
