app.get('/api/clientes',auth,async(req,res)=>res.json(await all(`SELECT c.id,c.whatsapp,c.nome,c.nome_whatsapp,c.nome_manual,c.casa,c.observacoes,COUNT(DISTINCT v.id) veiculos,(SELECT COUNT(*) FROM agendamentos a WHERE a.cliente_id=c.id AND a.status<>'cancelado') lavagens,(SELECT MAX(a.data) FROM agendamentos a WHERE a.cliente_id=c.id AND a.status<>'cancelado') ultima_lavagem FROM clientes c LEFT JOIN veiculos v ON v.cliente_id=c.id GROUP BY c.id ORDER BY c.id DESC LIMIT 200`)));
