app.post('/api/whatsapp/reiniciar',auth,async(req,res)=>{try{if(!waRestorable())return res.status(400).json({error:'Não existe sessão salva. Use Gerar novo QR Code.'});stopWa();setTimeout(()=>startWhatsApp({mode:'restore'}).catch(console.error),800);res.json({ok:true})}catch(e){res.status(500).json({error:e.message})}});
const mediaUpload=multer({storage:multer.memoryStorage(),limits:{fileSize:10*1024*1024},fileFilter:(req,file,cb)=>cb(null,/^image\/(jpeg|png|webp)$/.test(file.mimetype))});
app.get('/api/midias',auth,(req,res)=>res.json({menu:Array.from({length:5},(_,i)=>`/media/menu/menu-${String(i+1).padStart(2,'0')}.jpg`),anuncios:Array.from({length:5},(_,i)=>`/media/anuncios/anuncio-${String(i+1).padStart(2,'0')}.jpg`)}));
app.post('/api/midias/:tipo/:slot',auth,mediaUpload.single('foto'),async(req,res)=>{try{const type=req.params.tipo,slot=Number(req.params.slot);if(!['menu','anuncios'].includes(type)||slot<1||slot>5||!req.file)return res.status(400).json({error:'Foto ou posição inválida'});const dir=type==='menu'?MENU_DIR:AD_DIR,prefix=type==='menu'?'menu':'anuncio',filename=`${prefix}-${String(slot).padStart(2,'0')}.jpg`;await sharp(req.file.buffer).rotate().resize(1080,1080,{fit:'cover'}).jpeg({quality:82}).toFile(path.join(dir,filename));res.json({ok:true,url:`/media/${type}/${filename}?v=${Date.now()}`})}catch(e){res.status(400).json({error:'Não foi possível processar essa imagem'})}});
app.get('/api/campanhas',auth,async(req,res)=>{const year=Number(req.query.ano||isoBahia().slice(0,4)),dates=campaignDates(year);res.json((await all('SELECT * FROM campanhas ORDER BY rowid')).map(x=>({...x,data:dates[x.id]||null,imagem_url:x.imagem?`/media/campanhas/${encodeURIComponent(path.basename(x.imagem))}`:null})))});
app.put('/api/campanhas/:id',auth,async(req,res)=>{const current=await get('SELECT * FROM campanhas WHERE id=?',[req.params.id]);if(!current)return res.status(404).json({error:'Campanha não encontrada'});const ativo=req.body.ativo===undefined?current.ativo:(req.body.ativo?1:0),antecedencia=Math.max(0,Math.min(30,Number(req.body.antecedencia??current.antecedencia))),texto=String(req.body.texto??current.texto).trim(),imagem=req.body.imagem===undefined?current.imagem:path.basename(String(req.body.imagem||''));if(!texto)return res.status(400).json({error:'Texto obrigatório'});await run('UPDATE campanhas SET ativo=?,antecedencia=?,texto=?,imagem=?,updated_at=CURRENT_TIMESTAMP WHERE id=?',[ativo,antecedencia,texto,imagem||null,current.id]);res.json({ok:true})});
app.post('/api/campanhas/:id/imagem',auth,mediaUpload.single('foto'),async(req,res)=>{try{const campaign=await get('SELECT id FROM campanhas WHERE id=?',[req.params.id]);if(!campaign||!req.file)return res.status(400).json({error:'Campanha ou foto inválida'});const filename=`${campaign.id}.jpg`;await sharp(req.file.buffer).rotate().resize(1080,1080,{fit:'cover'}).jpeg({quality:82}).toFile(path.join(CAMPAIGN_DIR,filename));await run('UPDATE campanhas SET imagem=?,updated_at=CURRENT_TIMESTAMP WHERE id=?',[filename,campaign.id]);res.json({ok:true,url:`/media/campanhas/${filename}?v=${Date.now()}`})}catch(e){res.status(400).json({error:'Não foi possível processar essa imagem'})}});
app.post('/api/anuncios/teste',auth,async(req,res)=>{try{const slot=req.body?.horario==='12'?'12':'07',result=await sendScheduledAd(slot,{force:true});if(!result.sent){const messages={group_not_configured:'Conecte o WhatsApp, selecione o grupo e ative os anúncios automáticos.',no_availability:'Não há horários disponíveis para montar o anúncio.',send_failed:'O WhatsApp não conseguiu enviar o anúncio.'};return res.status(400).json({error:messages[result.reason]||'Não foi possível enviar o anúncio.',reason:result.reason})}res.json({ok:true,horario:slot})}catch(e){res.status(500).json({error:e.message})}});
const storage=multer.diskStorage({destination:(req,file,cb)=>cb(null,path.join(UP,req.params.tipo)),filename:(req,file,cb)=>cb(null,`${req.params.id}-${Date.now()}.jpg`)}),upload=multer({storage,limits:{fileSize:10*1024*1024},fileFilter:(req,file,cb)=>cb(null,/^image\/(jpeg|png|webp)$/.test(file.mimetype))});
app.post('/api/agendamento/:id/status',auth,async(req,res)=>{const a=await booking(req.params.id);if(!a)return res.sendStatus(404);const st=req.body.status;if(st==='indo'){if(a.status!=='agendado')return res.status(400).json({error:'O agendamento precisa estar confirmado'});await run('UPDATE agendamentos SET status="indo" WHERE id=?',[a.id]);await send(jid(a.whatsapp),`🚗 Oi, vizinho! Estou indo agora para a Casa ${a.casa}.\nDeixe o ${a.modelo} disponível, por favor. 🧽`)}else if(st==='iniciar'){if(a.status!=='indo')return res.status(400).json({error:'Use primeiro o botão ESTOU INDO'});if(!a.foto_antes)return res.status(400).json({error:'Foto ANTES obrigatória'});await run('UPDATE agendamentos SET status="lavando",inicio=datetime("now","localtime") WHERE id=?',[a.id]);await send(jid(a.whatsapp),`🚿 *LAVAGEM INICIADA!*\n\nJá comecei o cuidado do seu ${a.modelo}, vizinho. ✨`)}else return res.status(400).json({error:'Status inválido'});io.emit('refresh');res.json({ok:true})});
app.post('/api/agendamento/:id/foto/:tipo',auth,upload.single('foto'),async(req,res)=>{if(!['antes','depois'].includes(req.params.tipo)||!req.file)return res.status(400).json({error:'Foto inválida'});const a=await booking(req.params.id);if(!a)return res.sendStatus(404);if(req.params.tipo==='antes'&&!['indo','lavando'].includes(a.status))return res.status(400).json({error:'Use primeiro o botão ESTOU INDO'});if(req.params.tipo==='depois'&&a.status!=='lavando')return res.status(400).json({error:'Inicie a lavagem antes da foto DEPOIS'});await run(`UPDATE agendamentos SET foto_${req.params.tipo}=? WHERE id=?`,[req.file.filename,req.params.id]);io.emit('refresh');res.json({ok:true,file:req.file.filename})});
app.post('/api/agendamento/:id/finalizar',auth,async(req,res)=>{const a=await booking(req.params.id);if(!a)return res.sendStatus(404);if(!connected||!sock)return res.status(503).json({error:'WhatsApp desconectado. Reconecte antes de finalizar'});if(a.status!=='lavando')return res.status(400).json({error:'A lavagem precisa estar em andamento'});if(!a.foto_antes||!a.foto_depois)return res.status(400).json({error:'Fotos ANTES e DEPOIS são obrigatórias'});const stamp=Date.now(),out=`${a.id}-${stamp}.jpg`,publicOut=`${a.id}-${stamp}-grupo.jpg`;await montage(a,path.join(UP,'montagens',out),false);await montage(a,path.join(UP,'montagens',publicOut),true);await run('UPDATE agendamentos SET status="finalizado",fim=datetime("now","localtime"),montagem=? WHERE id=?',[out,a.id]);const buf=fs.readFileSync(path.join(UP,'montagens',out));try{await sock.sendMessage(jid(a.whatsapp),{image:buf,caption:`✨ *LAVAGEM CONCLUÍDA!*\n\nProntinho, vizinho! Seu ${a.modelo} ficou pronto. 🚗✨\nObrigado pela confiança no Harmony Car Wash.`})}catch(e){console.error('ENVIO CLIENTE',e.message)}const link=bookingLink();try{await sendGroupMessage(`✨ *MAIS UM FINALIZADO!* 🚗🧽\n\n🚘 ${a.modelo} — ${a.cor}\n🧽 ${a.servico}\n\nQuer deixar seu carro assim também?${link?`\n👉 ${link}`:' Chame o Harmony Car Wash no privado.'}`,path.join(UP,'montagens',publicOut))}catch(e){console.error('ENVIO GRUPO',e.message)}if(a.forma_pagamento===PAY_AFTER&&a.pagamento_status!=='paid'){try{await send(jid(a.whatsapp),'💳 Conforme escolhido no agendamento, agora enviaremos o PIX para pagamento da lavagem. Assim que o pagamento for confirmado, eu agradeço e peço sua avaliação.')}catch(e){console.error('AVISO PIX',e.message)}await generatePix(a.id,jid(a.whatsapp),false)}else await requestRating(jid(a.whatsapp),a.id);io.emit('refresh');res.json({ok:true,montagem:out})});
async function booking(id){return get(`SELECT a.*,c.nome,c.casa,c.whatsapp,c.documento,v.modelo,v.cor,s.nome servico,s.preco FROM agendamentos a JOIN clientes c ON c.id=a.cliente_id JOIN veiculos v ON v.id=a.veiculo_id JOIN servicos s ON s.id=a.servico_id WHERE a.id=?`,[id])}
async function montage(a,out,publicVersion=false){const A=path.join(UP,'antes',a.foto_antes),B=path.join(UP,'depois',a.foto_depois),W=1200,H=900;const aa=await sharp(A).resize(600,650,{fit:'cover'}).jpeg().toBuffer(),bb=await sharp(B).resize(600,650,{fit:'cover'}).jpeg().toBuffer();const privacy=publicVersion?'<rect x="190" y="570" width="220" height="85" rx="18" fill="#102b4e" fill-opacity="0.94"/><rect x="790" y="570" width="220" height="85" rx="18" fill="#102b4e" fill-opacity="0.94"/><text x="220" y="622" fill="white" font-size="22" font-family="Arial" font-weight="700">PRIVACIDADE</text><text x="820" y="622" fill="white" font-size="22" font-family="Arial" font-weight="700">PRIVACIDADE</text>':'';const svg=Buffer.from(`<svg width="${W}" height="${H}"><rect width="100%" height="130" fill="#0f2747"/><text x="60" y="65" fill="white" font-size="42" font-family="Arial" font-weight="700">HARMONY CAR WASH</text><text x="60" y="108" fill="#cfe8ff" font-size="24" font-family="Arial">Harmony Residence • ${a.modelo} — ${a.cor}</text>${privacy}<rect y="780" width="100%" height="120" fill="#0f2747"/><text x="180" y="850" fill="white" font-size="36" font-family="Arial" font-weight="700">ANTES</text><text x="850" y="850" fill="white" font-size="36" font-family="Arial" font-weight="700">DEPOIS</text></svg>`);await sharp({create:{width:W,height:H,channels:3,background:'#f8fafc'}}).composite([{input:aa,left:0,top:130},{input:bb,left:600,top:130},{input:svg,left:0,top:0}]).jpeg({quality:90}).toFile(out)}
function htmlFile(name){
 const inPublic=path.join(__dirname,'public',name);
 return fs.existsSync(inPublic)?inPublic:path.join(__dirname,name);
}
app.get('/operacao',auth,(req,res)=>res.sendFile(htmlFile('operacao.html')));app.get('/admin',(req,res)=>res.sendFile(htmlFile('admin.html')));app.get('/health',(req,res)=>res.json({ok:true,whatsapp:connected,configured:!!settings.operation_token}));
init().then(()=>{server.listen(PORT,()=>console.log('Harmony Car Wash na porta',PORT));if(waRestorable())startWhatsApp({mode:'restore'});else{waStatus='AGUARDANDO_ACAO';console.log('📲 HARMONY: abra o painel e clique em Gerar novo QR Code')};startAutomations();resumePendingPayments().catch(console.error)}).catch(console.error);
